// FABLE_RETAIL_CDEFINITIONMANAGER_GETDEF_GLOBAL_BODY = the out-of-line instance native 0x00513160 / FableWin 0x01CCD240). That
// opt-in declares it __declspec(noinline); this TU instead EXPANDS GetDef<CThingObjectDef> in the book loop (no call to a GetDef
// COMDAT; GetPDefFromGlobalIndex 0x009AD9E0 is called directly from the row), so the same text is repeated here without noinline.
// One difference from the header text: the null test is spelled `!def.IsNull()` (CDefPointer.h `Object == 0`), not `def.Get()`.
// Both test the same word, but the def.Get() spelling flips the IL order of the category loop's &vector[i] to `lea esi,[eax+ecx]`
// at 0x006090E7 (retail `lea esi,[ecx+eax]`); !def.IsNull() is the spelling that gives retail's bytes (graded both, repair session).
template <class T>
bool CDefinitionManager::GetDef(long index, CDefPointer<const T>* out) const
{
    if (index > 0) {
        CDefPointer<const CDefClassBase> def = GetPDefFromGlobalIndex(index);
        if (!def.IsNull()) {
            out->SetDynamicCast(def);
            return true;
        }
    }
    return false;
}

